let __v_264 = Value::from("Treat it as a small Saturday: one thing out of the house (a walk you have not done, a market, a museum or gallery - most are free), one job you keep putting off that takes an hour, and one person to see. Put times on the first two the night before; a free day goes in small pieces when nothing is decided.");
